# Triplet loss (simplified)
import math

def distance(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

def triplet_loss(anchor, positive, negative, margin=0.2):
    pos_dist = distance(anchor, positive)
    neg_dist = distance(anchor, negative)
    return max(0.0, pos_dist - neg_dist + margin)

anchor = [0.5, 0.5]
pos    = [0.6, 0.55]
neg    = [0.1, 0.9]

print(f"triplet loss: {triplet_loss(anchor, pos, neg):.4f}")
print("Goal: make pos_dist small and neg_dist large")

import math

def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    ma = math.sqrt(sum(x * x for x in a))
    mb = math.sqrt(sum(x * x for x in b))
    return dot / (ma * mb)

def euclidean(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

a = [1.0, 0.0, 0.0]
b = [2.0, 0.0, 0.0]   # same direction, different magnitude

print(f"cosine: {cosine(a, b):.3f}")      # 1.0 (identical direction)
print(f"euclidean: {euclidean(a, b):.3f}")   # 1.0 (different magnitude)

import math

query = [0.9, 0.1, 0.0]
database = {
    "doc_a": [0.85, 0.15, 0.0],
    "doc_b": [0.1, 0.9, 0.0],
    "doc_c": [0.8, 0.2, 0.05],
    "doc_d": [0.0, 0.0, 1.0],
}

def cosine(a, b):
    d = sum(x * y for x, y in zip(a, b))
    ma = math.sqrt(sum(x * x for x in a))
    mb = math.sqrt(sum(x * x for x in b))
    return d / (ma * mb)

results = sorted(
    ((name, cosine(query, emb)) for name, emb in database.items()),
    key=lambda x: -x[1]
)

for name, score in results:
    print(f"{name}: {score:.3f}")

